const NOW = Date.now();
const cfg = (($('Config ophalen').all()[0]||{}).json)||{};
const TH  = (cfg.thresholds && cfg.thresholds.default) || {};
const OFFLINE_MIN = TH.offline_min ?? 10, UPD_MANY = TH.updates_many ?? 20;
const BAT_MIN = TH.bat_min ?? 15, DISK_WARN = TH.disk_warn ?? 80, DISK_ALARM = TH.disk_alarm ?? 90;
const TEMP_ALARM = TH.temp_alarm ?? 90;
const num = v => (v==null||v==='')?NaN:Number(v);
const tms = r => Date.parse(r.ts);
const hhmm = () => new Date(NOW).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Amsterdam'});
const asArr = v => Array.isArray(v)?v:(typeof v==='string'?(()=>{try{return JSON.parse(v)}catch(e){return null}})():null);
const rows = $input.all().map(i=>i.json);          // v_latest: 1 rij per machine
const online = rows.filter(r=>!isNaN(tms(r)) && (NOW-tms(r))/60000 <= OFFLINE_MIN);
const label = m => (m||'?');

const t=hhmm(); const store=$getWorkflowStaticData('global'); store.b=store.b||{};
const out=[];
for(const d of online){
  const m=label(d.machine); const bat=num(d.battery); const plug=d.bat_plugged; const health=num(d.bat_health);
  if(isNaN(bat)) continue;                       // geen accu (desktop)
  const crit = plug===false && bat<BAT_MIN;
  const id=m+':crit'; const was=!!store.b[id];
  if(crit&&!was){store.b[id]=true;
    out.push({json:{caption:'\u26A0 Accu kritiek \u2014 '+m+' \u00b7 '+Math.round(bat)+'%',
      spec:{title:'\u26A0 Accu bijna leeg \u2014 '+m,subtitle:'op accu \u00b7 '+t,state:'alert',
        rows:[{label:'ACCU',value:Math.round(bat)+'% op accu',pct:bat,status:'high'}],footer:'SysDash \u00b7 onder '+BAT_MIN+'% \u00b7 '+t}}});}
  else if(!crit&&was){store.b[id]=false;
    out.push({json:{caption:'\u2713 Accu weer ok \u2014 '+m,
      spec:{title:'\u2713 Accu hersteld \u2014 '+m,subtitle:t,state:'ok',
        rows:[{label:'ACCU',value:Math.round(bat)+'%'+(plug?' \u00b7 aan stroom':''),status:'ok'}],footer:'SysDash \u00b7 accu \u00b7 '+t}}});}
  // slijtage (Laag 2): eenmalig seintje als conditie < 30
  if(!isNaN(health)&&health<30){const wid=m+':wear';if(!store.b[wid]){store.b[wid]=true;
    out.push({json:{caption:'\u25CF Accu-slijtage \u2014 '+m+' \u00b7 conditie '+Math.round(health)+'%',
      spec:{title:'\u25CF Accu versleten \u2014 '+m,subtitle:t,state:'ok',
        rows:[{label:'CONDITIE',value:Math.round(health)+'% van origineel',status:'warn'}],footer:'SysDash \u00b7 accu-conditie \u00b7 '+t}}});}}
}
return out;
